// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisIssuanceAuctionBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("AuctionNotSettled()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeAuctionNotSettledError(raw)
	}
	if definition, err := c.customError("InvalidUnpricedPerpRegistration()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidUnpricedPerpRegistrationError(raw)
	}
	if definition, err := c.customError("IssuanceAuctionCallFailed()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeIssuanceAuctionCallFailedError(raw)
	}
	if definition, err := c.customError("RegistrationConflict()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRegistrationConflictError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
